SHAPES_AREA = '''"""Area helpers."""
import math


def square_area(side):
    """Return the area of a square."""
    return side * side


def _unit():
    return 1


def _scale(value):
    return value * _unit()


def _half(value):
    return value / 2


def circle_area(radius):
    """Return the area of a circle."""
    return math.pi * radius * radius
'''

SHAPES_AREA_MASKED = '''"""Area helpers."""
import math


def _unit():
    return 1


def _scale(value):
    return value * _unit()


def _half(value):
    return value / 2
'''

SHAPES_AREA_TEST = '''import math

from shapes.area import circle_area, square_area


def test_square_area():
    assert square_area(3) == 9


def test_circle_area():
    assert circle_area(1) == math.pi
'''

PROJECTS = {
    "fixture/calc": {
        "calc/__init__.py": "from .ops import add, div, mul\n",
        "calc/ops.py": CALC_OPS,
        "tests/test_ops.py": CALC_TESTS,
    },
    "fixture/calcgo": {
        "go.mod": "module example.com/calcgo\n\ngo 1.21\n",
        "calc.go": CALC_GO,
        "calc_test.go": CALC_GO_TEST,
    },
    "fixture/calcrs": {
        "Cargo.toml": '[package]\nname = "calcrs"\nversion = "0.1.0"\nedition = "2021"\n\n[dependencies]\n',
        "Cargo.lock": "# This file is automatically @generated by Cargo.\n# It is not intended for manual editing.\n"
                      'version = 3\n\n[[package]]\nname = "calcrs"\nversion = "0.1.0"\n',
        "src/lib.rs": CALC_RS,
        "tests/calc.rs": CALC_RS_TEST,
    },
    "fixture/shapes": {
        "shapes/__init__.py": '"""Shape helpers."""\n',
        "shapes/area.py": SHAPES_AREA,
        "shapes/misc.py": 'def label(name):\n    return f"<{name}>"\n',
        "tests/test_area.py": SHAPES_AREA_TEST,
        "tests/test_misc.py": 'from shapes.misc import label\n\n\ndef test_label():\n    assert label("a") == "<a>"\n',
    },
}

# Gold fixes and held-out test additions for the SWE-bench-shaped instances.
SWE = {
    "fixture/calc": {
        "instance_id": "fixture__calc-1",
        "fix": {"calc/ops.py": CALC_OPS.replace("return left + right\n\n\ndef negate", "return left * right\n\n\ndef negate")
                .replace("left // right + 1", "left // right")},
        "tests": {"tests/test_ops.py": CALC_TESTS.replace("from calc import add", "from calc import add, div, mul")
                  + "\n\ndef test_mul():\n    assert mul(2, 3) == 6\n\n\ndef test_div():\n    assert div(7, 2) == 3\n"},
        "command": "python -m pytest -rA tests/test_ops.py",
        "f2p": ["tests/test_ops.py::test_mul", "tests/test_ops.py::test_div"],
        "p2p": ["tests/test_ops.py::test_add"],
    },
    "fixture/calcgo": {
        "instance_id": "fixture__calcgo-2",
        "fix": {"calc.go": CALC_GO.replace("\treturn a + b\n", "\treturn a * b\n").replace("a/b + 1", "a / b")},
        "tests": {"calc_test.go": CALC_GO_TEST + "\nfunc TestMul(t *testing.T) {\n\tif Mul(2, 3) != 6 {\n\t\tt.Fatal(\"mul\")\n\t}\n}\n"
                  "\nfunc TestDiv(t *testing.T) {\n\tif Div(7, 2) != 3 {\n\t\tt.Fatal(\"div\")\n\t}\n}\n"},
        "command": '(go test -v . -run "^Test") | cat',
        "f2p": ["TestMul", "TestDiv"],
        "p2p": ["TestAdd"],
    },
    "fixture/calcrs": {
        "instance_id": "fixture__calcrs-3",
        "fix": {"src/lib.rs": CALC_RS.replace("pub fn mul(a: i64, b: i64) -> i64 {\n    a + b", "pub fn mul(a: i64, b: i64) -> i64 {\n    a * b")
                .replace("a / b + 1", "a / b")},
        "tests": {"tests/calc.rs": CALC_RS_TEST.replace("use calcrs::add;", "use calcrs::{add, div, mul};")
                  + "\n#[test]\nfn mul_works() {\n    assert_eq!(mul(2, 3), 6);\n}\n"
                  "\n#[test]\nfn div_works() {\n    assert_eq!(div(7, 2), 3);\n}\n"},
        "command": "(RUSTFLAGS=-Awarnings cargo test --test calc) | cat",
        "f2p": ["mul_works", "div_works"],
        "p2p": ["add_works"],
    },
}

EVAL_SCRIPT = """#!/bin/bash
set -uxo pipefail
cd /testbed
git config --global --add safe.directory /testbed
git status
git show
git -c core.fileMode=false diff {base}
git checkout {base} {test_files}
git apply -v - <<'EOF_114329324912'
{test_patch}
EOF_114329324912
: '>>>>> Start Test Output'
{command}
: '>>>>> End Test Output'
git checkout {base} {test_files}
"""

REPO_SETTINGS = {
    "repository": "fixture/shapes", "commit": "", "clone_method": "https", "base_url": None,
    "base_image": "python311", "rebuild_base_image": False, "rebuild_instance_image": False,
    "custom_instance_image_build": [], "pre_install": [], "install": "pip install -e .",
    "pip_packages": ["pytest"],
    "docker_specs": {"run_args": {"cuda_visible_devices": "6,7", "shm_size": None, "cap_add": []},
                     "custom_docker_args": []},
    "test_cmd": "pytest -rA --tb=short --color=no", "timeout_run": 600, "library_name": "shapes",
    "black_links": ["https://github.com/fixture/shapes"], "technical_docs": [],
}

FB_PROBLEM = """## Task
**Task Statement:**

Implement ``square_area`` and ``circle_area`` in ``shapes.area``: return the
area of a square from its side length and of a circle from its radius.

You are forbidden to access the following URLs:
black_links:
- https://github.com/fixture/shapes
"""


def diff(work: Path, files: dict[str, str | None]) -> str:
    """Return the git diff that turns the checked-out base into ``files`` (None deletes)."""
    for relative, content in files.items():
        path = work / relative
        if content is None:
            path.unlink()
        else:
            write_tree(work, {relative: content})
    patch = git("diff", "--no-color", "HEAD", cwd=work)
    git("reset", "-q", "--hard", "HEAD", cwd=work)
    git("clean", "-qfd", cwd=work)
    return patch


def main() -> None:
    swe_rows, fb_rows = [], []
    with tempfile.TemporaryDirectory() as temp:
        root = Path(temp)
        for repo, files in PROJECTS.items():
            bare, base = build_upstream(repo, files, root / "upstream")
            work = root / "checkout" / repo
            git("clone", "-q", str(bare), str(work), cwd=root)
            if repo in SWE:
                spec = SWE[repo]
                test_patch = diff(work, spec["tests"])
                swe_rows.append({
                    "base_commit": base, "created_at": "2026-01-01 00:00:00", "eval_type": "pass_and_fail",
                    "image": f"swebench/sweb.eval.x86_64.{spec['instance_id']}:latest",
                    "instance_id": spec["instance_id"],
                    "log_parser": {"python": "parse_log_pytest", "go": "parse_log_gotest", "rust": "parse_log_cargo"}[
                        {"fixture/calc": "python", "fixture/calcgo": "go", "fixture/calcrs": "rust"}[repo]],
                    "repo": repo, "version": spec["instance_id"].rsplit("-", 1)[1],
                    "patch": diff(work, spec["fix"]),
                    "test_patch": test_patch,
                    "eval_script": EVAL_SCRIPT.format(base=base, test_files=" ".join(spec["tests"]),
                                                      test_patch=test_patch.rstrip("\n"), command=spec["command"]),
                    "problem_statement": f"{repo}: mul and div return wrong results.\n",
                    "hints_text": "",
                    "FAIL_TO_PASS": spec["f2p"], "PASS_TO_PASS": spec["p2p"],
                })
                continue
            mask = diff(work, {"shapes/area.py": SHAPES_AREA_MASKED})
            mask_editing_f2p = diff(work, {
                "shapes/area.py": SHAPES_AREA_MASKED,
                "tests/test_area.py": SHAPES_AREA_TEST.replace("from shapes.area import circle_area, square_area\n", ""),
            })
            test_patch = diff(work, {"tests/test_area.py": None})
            settings = json.dumps({**REPO_SETTINGS, "commit": base[:7]})
            for instance_id, patch in (
                ("fixture__shapes.0a1b2c3d.test_area.5e6f7a8b.lv1", mask),
                ("fixture__shapes.0a1b2c3d.test_area.9c0d1e2f.lv1", mask_editing_f2p),
                ("fixture__shapes.0a1b2c3d.test_area.5e6f7a8b.lv2", mask),
            ):
                fb_rows.append({
                    "instance_id": instance_id, "patch": patch, "test_patch": test_patch,
                    "FAIL_TO_PASS": ["tests/test_area.py"], "PASS_TO_PASS": ["tests/test_misc.py"],
                    "image_name": "libercoders/featurebench-specs_shapes-instance_00000000",
                    "repo": repo, "base_commit": base, "problem_statement": FB_PROBLEM,
                    "repo_settings": settings,
                })
            shutil.rmtree(work)
    (HERE / "projects.json").write_text(json.dumps(PROJECTS, indent=1) + "\n")
    (HERE / "swebench_ml_rows.json").write_text(json.dumps(swe_rows, indent=1) + "\n")
    (HERE / "featurebench_rows.json").write_text(json.dumps(fb_rows, indent=1) + "\n")


if __name__ == "__main__":
    main()
